    Reply api(String method,String path,Object body,String token,String key) throws Exception {
        var builder=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(Duration.ofSeconds(25));if(token!=null)builder.header("Authorization","Bearer "+token);if(key!=null)builder.header("Idempotency-Key",key);if(body!=null)builder.header("Content-Type","application/json");builder.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));var response=http.send(builder.build(),HttpResponse.BodyHandlers.ofString());requests.add(Map.of("method",method,"path",path,"status",response.statusCode()));return new Reply(response.statusCode(),json.readTree(response.body()));
    }
    void ok(Reply r) {assertEquals(200,r.status(),r.body().toString());}void error(Reply r,int status,String code) {assertEquals(status,r.status(),r.body().toString());assertEquals(code,r.body().at("/error/code").asString());}
    String login(String user) throws Exception {var r=api("POST","/auth/login",Map.of("username",user,"password","qixu-demo","mode","BEARER"),null,null);ok(r);return r.data().path("token").asString();}
    String iso(Instant time) {return time.toString();}
    Map<String,Object> batchBody(List<Long> pool) {
        var now=clock.value;return new LinkedHashMap<>(Map.ofEntries(Map.entry("title","治理验收轮次"),Map.entry("purpose","POSTGRADUATE"),Map.entry("startsAt",iso(now.plusSeconds(4200))),Map.entry("endsAt",iso(now.plusSeconds(864000))),Map.entry("opensAt",iso(now.minusSeconds(1))),Map.entry("closesAt",iso(now.plusSeconds(300))),Map.entry("freezeDeadline",iso(now.plusSeconds(360))),Map.entry("randomAt",iso(now.plusSeconds(420))),Map.entry("resultDeadline",iso(now.plusSeconds(1200))),Map.entry("confirmationDeadline",iso(now.plusSeconds(3600))),Map.entry("promotionUntil",iso(now.plusSeconds(864000))),Map.entry("promotionSeconds",600),Map.entry("seatIds",pool)));
    }
    long open(String admin,List<Long> pool,String key) throws Exception {var r=api("POST","/preparation-batches",batchBody(pool),admin,key);ok(r);return r.id();}
    Map<String,Object> application(long seat) {return Map.of("version",0,"preferences",List.of(Map.of("seatId",seat,"rank",1)),"keepWaitlist",true);}
    void submit(String owner,long batch,long seat,String key) throws Exception {ok(api("POST","/preparation-batches/"+batch+"/application",application(seat),owner,key));}
    void draw(String admin,long batch) throws Exception {clock.value=Instant.parse("2026-10-10T01:05:00Z");ok(api("POST","/preparation-batches/"+batch+"/actions",Map.of("version",1,"action","FREEZE"),admin,"governance-freeze"));clock.value=Instant.parse("2026-10-10T01:07:03Z");ok(api("POST","/preparation-batches/"+batch+"/actions",Map.of("version",2,"action","ALLOCATE"),admin,"governance-allocate"));}
    Fixture fixture() throws Exception {
        var admin=login("admin1");var owner=login("student1");long batch=open(admin,List.of(2000L),"governance-batch");submit(owner,batch,2000,"governance-application");draw(admin,batch);long offer=jdbc.queryForObject("SELECT id FROM long_offer WHERE batch_id=? AND user_id=1",Long.class,batch);ok(api("POST","/long-offers/"+offer+"/actions",Map.of("version",1,"action","ACCEPT"),owner,"governance-accept"));return new Fixture(admin,owner,batch,offer,jdbc.queryForObject("SELECT id FROM seat_entitlement WHERE offer_id=?",Long.class,offer));
    }
    Map<String,Object> caseBody(Fixture f) {return new LinkedHashMap<>(Map.of("entitlementId",f.right(),"entitlementVersion",1,"reasonCode","EXPLICIT_RULE_VIOLATION","evidence","验收专用私有事实 PRIVATE_CASE_9922，不得公开","statementUntil",iso(clock.value.plusSeconds(86400))));}
    Reply create(Fixture f) throws Exception {var r=api("POST","/admin/governance-cases",caseBody(f),f.admin(),"governance-notice");ok(r);return r;}
    long version(long id) {return jdbc.queryForObject("SELECT version FROM governance_case WHERE id=?",Long.class,id);}
    void due(long id) {clock.value=Business.date(jdbc.queryForMap("SELECT statement_until FROM governance_case WHERE id=?",id),"statement_until").toInstant(ZoneOffset.UTC);}
    Reply decision(String admin,long id,String action,String penalty,String key) throws Exception {var body=new LinkedHashMap<String,Object>(Map.of("version",version(id),"action",action,"reason","有明确依据的裁决，非勤奋或签到指标"));if(penalty!=null)body.put("penaltyUntil",penalty);return api("POST","/admin/governance-cases/"+id+"/decisions",body,admin,key);}
    Reply appeal(String owner,long id) throws Exception {return api("POST","/governance-cases/"+id+"/appeals",Map.of("version",version(id),"message","请核实原记录，本案存在事实错误"),owner,"governance-appeal");}
    Reply review(String reviewer,long id,String key) throws Exception {return api("POST","/admin/governance-cases/"+id+"/reviews",Map.of("version",version(id),"action","OVERTURN","reason","独立复核确认原裁决错误"),reviewer,key);}
    long future(String admin,Instant close,String key) throws Exception {
        var body=batchBody(List.of(2003L));body.put("startsAt","2026-10-21T02:00:00Z");body.put("endsAt","2026-10-25T02:00:00Z");body.put("promotionUntil","2026-10-25T02:00:00Z");body.put("closesAt",iso(close));body.put("freezeDeadline",iso(close.plusSeconds(60)));body.put("randomAt",iso(close.plusSeconds(120)));body.put("resultDeadline",iso(close.plusSeconds(900)));body.put("confirmationDeadline",iso(close.plusSeconds(3600)));var r=api("POST","/preparation-batches",body,admin,key);ok(r);return r.id();
    }
    void freezeFuture(String admin,long batch) throws Exception {clock.value=Business.date(jdbc.queryForMap("SELECT closes_at FROM preparation_batch WHERE id=?",batch),"closes_at").toInstant(ZoneOffset.UTC);ok(api("POST","/preparation-batches/"+batch+"/actions",Map.of("version",1,"action","FREEZE"),admin,"freeze-future-round"));}
    Reply allocateFuture(String admin,long batch) throws Exception {clock.value=Business.date(jdbc.queryForMap("SELECT random_at FROM preparation_batch WHERE id=?",batch),"random_at").toInstant(ZoneOffset.UTC).plusSeconds(3);return api("POST","/preparation-batches/"+batch+"/actions",Map.of("version",2,"action","ALLOCATE"),admin,"allocate-future-round");}
