        var record=create(f);error(api("GET","/governance-cases/"+record.id(),null,login("student2"),null),404,"RESOURCE_NOT_FOUND");error(api("POST","/admin/governance-cases",caseBody(f),f.owner(),"student-notice-control"),403,"SCOPE_FORBIDDEN");error(decision(f.admin(),record.id(),"REVOKE",null,"premature-revocation"),409,"STATEMENT_WINDOW_OPEN");
        assertEquals("ACTIVE",jdbc.queryForObject("SELECT status FROM seat_entitlement WHERE id=?",String.class,f.right()));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM long_application_penalty",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM governance_case",Integer.class));assertFalse(api("GET","/spaces/2000",null,login("student2"),null).body().toString().contains("PRIVATE_CASE"));
