        String output=jdbc.queryForObject("SELECT output_hash FROM allocation_result WHERE batch_id=?",String.class,f.batch());ok(decision(login("admin1"),record.id(),"REVOKE",null,"governance-revoke"));assertEquals(output,jdbc.queryForObject("SELECT output_hash FROM allocation_result WHERE batch_id=?",String.class,f.batch()));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM governance_history WHERE action='STATEMENT'",Integer.class));assertEquals("REVOKED",jdbc.queryForObject("SELECT status FROM seat_entitlement WHERE id=?",String.class,f.right()));
