    @Test void appealCannotStealASeatAlreadyAcceptedByTheStableWaitlist() throws Exception {
        var admin=login("admin1");var one=login("student1");var two=login("student2");long batch=open(admin,List.of(2000L),"two-person-batch");submit(one,batch,2000,"two-person-one");submit(two,batch,2000,"two-person-two");draw(admin,batch);
        var offered=jdbc.queryForMap("SELECT id,user_id FROM long_offer WHERE batch_id=?",batch);long user=Business.number(offered,"user_id"),offer=Business.number(offered,"id");var winner=user==1?one:two;ok(api("POST","/long-offers/"+offer+"/actions",Map.of("version",1,"action","ACCEPT"),winner,"first-winner-accept"));long right=jdbc.queryForObject("SELECT id FROM seat_entitlement WHERE offer_id=?",Long.class,offer);var record=create(new Fixture(admin,winner,batch,offer,right));String output=jdbc.queryForObject("SELECT output_hash FROM allocation_result WHERE batch_id=?",String.class,batch);
        due(record.id());admin=login("admin1");ok(decision(admin,record.id(),"REVOKE",null,"winner-revoked"));seats.maintain(batch);var promoted=jdbc.queryForMap("SELECT id,user_id FROM long_offer WHERE batch_id=? AND status='OPEN'",batch);assertNotEquals(user,Business.number(promoted,"user_id"));var next=login(user==1?"student2":"student1");ok(api("POST","/long-offers/"+promoted.get("id")+"/actions",Map.of("version",1,"action","ACCEPT"),next,"stable-waitlist-accept"));
        ok(appeal(login(user==1?"student1":"student2"),record.id()));var correction=review(login("admin2"),record.id(),"cannot-steal-restoration");ok(correction);assertEquals("CORRECTED_UNAVAILABLE",correction.data().path("status").asString());assertEquals("SPACE_CONFLICT",correction.data().path("restoration_reason").asString());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM seat_entitlement WHERE status='ACTIVE'",Integer.class));assertEquals("REVOKED",jdbc.queryForObject("SELECT status FROM seat_entitlement WHERE id=?",String.class,right));assertEquals(output,jdbc.queryForObject("SELECT output_hash FROM allocation_result WHERE batch_id=?",String.class,batch));
    }
