    @Test void administratorLosingScopeWhileWaitingCannotRevokeTheRight() throws Exception {
        var f=fixture();var record=create(f);due(record.id());var admin=login("admin1");var gate=new CountDownLatch(1);var executor=Executors.newSingleThreadExecutor();final Future<Reply>[] pending=new Future[1];
        org.mockito.Mockito.doAnswer(inv->{gate.countDown();return inv.callRealMethod();}).when(business).floors(org.mockito.ArgumentMatchers.anyCollection());
        try {new TransactionTemplate(manager).execute(status->{jdbc.queryForList("SELECT id FROM floor WHERE id=100 FOR UPDATE");pending[0]=executor.submit(()->decision(admin,record.id(),"REVOKE",null,"scope-revoked-during-wait"));try {assertTrue(gate.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new RuntimeException(e);}jdbc.update("DELETE FROM admin_scope WHERE user_id=4 AND floor_id=100");return null;});error(pending[0].get(20,TimeUnit.SECONDS),403,"SCOPE_FORBIDDEN");assertEquals("ACTIVE",jdbc.queryForObject("SELECT status FROM seat_entitlement WHERE id=?",String.class,f.right()));}
        finally {executor.shutdownNow();jdbc.update("INSERT IGNORE INTO admin_scope(user_id,floor_id) VALUES(4,100)");org.mockito.Mockito.reset(business);}
    }
    @Test void concurrentDecisionsCannotOverwriteEachOtherWithTheSameVersion() throws Exception {
        var f=fixture();var record=create(f);due(record.id());var one=login("admin1");var two=login("admin2");var executor=Executors.newFixedThreadPool(2);var go=new CountDownLatch(1);var body1=Map.of("version",1,"action","REVOKE","reason","第一份合法裁决");var body2=Map.of("version",1,"action","DISMISS","reason","另一位管理员的不同判断");
        try {var a=executor.submit(()->{go.await();return api("POST","/admin/governance-cases/"+record.id()+"/decisions",body1,one,"decision-race-a");});var c=executor.submit(()->{go.await();return api("POST","/admin/governance-cases/"+record.id()+"/decisions",body2,two,"decision-race-b");});go.countDown();assertEquals(List.of(200,409),List.of(a.get(20,TimeUnit.SECONDS).status(),c.get(20,TimeUnit.SECONDS).status()).stream().sorted().toList());assertEquals(2,version(record.id()));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM governance_history WHERE action IN ('REVOKED','DISMISSED')",Integer.class));}
        finally {executor.shutdownNow();}
    }
