    @Test void unusedPublishedCancellationRejectsLiveOfferThenRetainsFormalResultWhenExpired() throws Exception {
        var admin=login("admin1");var owner=login("student1");long batch=open(admin,List.of(2000L),"cancel-unused-batch");submit(owner,batch,2000,"cancel-unused-application");draw(admin,batch);var body=Map.of("version",3,"action","CANCEL_UNUSED","reason","没有授予过使用权的废弃轮次");error(api("POST","/preparation-batches/"+batch+"/cancel",body,admin,"cancel-live-offer"),409,"BATCH_HAS_GRANTED_RIGHTS");String output=jdbc.queryForObject("SELECT output_hash FROM allocation_result WHERE batch_id=?",String.class,batch);clock.value=Instant.parse("2026-10-10T02:00:00Z");ok(api("POST","/preparation-batches/"+batch+"/cancel",body,admin,"cancel-expired-round"));assertEquals(output,jdbc.queryForObject("SELECT output_hash FROM allocation_result WHERE batch_id=?",String.class,batch));assertEquals("CANCELED",jdbc.queryForObject("SELECT status FROM long_offer WHERE batch_id=?",String.class,batch));
    }
    @Test void aRoundWithConfirmedHistoryCannotUseTheUnusedCancellationShortcut() throws Exception {
        var f=fixture();ok(api("POST","/preparation-batches/"+f.batch()+"/exit",Map.of("version",1,"action","EXIT"),f.owner(),"exit-before-unused-cancel"));error(api("POST","/preparation-batches/"+f.batch()+"/cancel",Map.of("version",3,"action","CANCEL_UNUSED","reason","不能借废弃入口洗掉确认历史"),f.admin(),"cancel-confirmed-history"),409,"BATCH_HAS_GRANTED_RIGHTS");assertEquals("RESULT_PUBLISHED",jdbc.queryForObject("SELECT status FROM preparation_batch WHERE id=?",String.class,f.batch()));assertEquals("RELINQUISHED",jdbc.queryForObject("SELECT status FROM seat_entitlement WHERE id=?",String.class,f.right()));
    }
    @Test void penaltyIntroducedAfterSubmissionExcludesTheCandidateAtFreezeWithoutChangingTheSubmittedVersion() throws Exception {
        var f=fixture();var record=create(f);var deadline=clock.value.plusSeconds(86400);long next=future(f.admin(),deadline.plusSeconds(3),"eligibility-freeze-batch");submit(f.owner(),next,2003,"eligibility-before-freeze");due(record.id());var admin=login("admin1");ok(decision(admin,record.id(),"REVOKE",iso(clock.value.plusSeconds(86400)),"eligibility-freeze-revoke"));freezeFuture(admin,next);
        assertEquals("EXCLUDED",jdbc.queryForObject("SELECT status FROM preparation_application WHERE batch_id=? AND user_id=1",String.class,next));assertEquals("ELIGIBILITY_INVALID_AT_FREEZE",jdbc.queryForObject("SELECT reason FROM preparation_application WHERE batch_id=? AND user_id=1",String.class,next));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM frozen_person WHERE batch_id=?",Integer.class,next));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM application_version v JOIN preparation_application a ON v.application_id=a.id WHERE a.batch_id=?",Integer.class,next));
        assertEquals("LONG_APPLICATION_PENALTY",api("GET","/preparation-batches/"+next+"/application",null,login("student1"),null).data().at("/currentEligibility/reason").asString());
    }
    @Test void penaltyAfterFreezeStopsWholePublicationInsteadOfSilentlyShrinkingFrozenPeople() throws Exception {
        var f=fixture();var record=create(f);var deadline=clock.value.plusSeconds(86400);long next=future(f.admin(),deadline.minusSeconds(120),"eligibility-publication-batch");submit(f.owner(),next,2003,"eligibility-before-publication");clock.value=deadline.minusSeconds(120);var admin=login("admin1");freezeFuture(admin,next);String hash=jdbc.queryForObject("SELECT input_hash FROM frozen_input WHERE batch_id=?",String.class,next);due(record.id());ok(decision(admin,record.id(),"REVOKE",iso(clock.value.plusSeconds(86400)),"eligibility-publication-revoke"));ok(allocateFuture(admin,next));
        assertEquals("FAILED_NO_RESULT",jdbc.queryForObject("SELECT status FROM preparation_batch WHERE id=?",String.class,next));assertEquals("INPUT_INVALIDATED_ELIGIBILITY",jdbc.queryForObject("SELECT failure_reason FROM preparation_batch WHERE id=?",String.class,next));assertEquals(hash,jdbc.queryForObject("SELECT input_hash FROM frozen_input WHERE batch_id=?",String.class,next));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM frozen_person WHERE batch_id=?",Integer.class,next));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM allocation_result WHERE batch_id=?",Integer.class,next));
    }
    @Test void anOpenOfferCannotBeConfirmedAfterCurrentQualificationIsRevoked() throws Exception {
        var f=fixture();var record=create(f);var deadline=clock.value.plusSeconds(86400);long next=future(f.admin(),deadline.minusSeconds(180),"eligibility-confirmation-batch");submit(f.owner(),next,2003,"eligibility-before-confirmation");clock.value=deadline.minusSeconds(180);var admin=login("admin1");freezeFuture(admin,next);ok(allocateFuture(admin,next));long offer=jdbc.queryForObject("SELECT id FROM long_offer WHERE batch_id=? AND user_id=1",Long.class,next);due(record.id());ok(decision(admin,record.id(),"REVOKE",iso(clock.value.plusSeconds(86400)),"eligibility-confirmation-revoke"));
        error(api("POST","/long-offers/"+offer+"/actions",Map.of("version",1,"action","ACCEPT"),login("student1"),"confirmation-after-penalty"),409,"LONG_APPLICATION_PENALTY");assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM seat_entitlement WHERE batch_id=?",Integer.class,next));assertEquals("OPEN",jdbc.queryForObject("SELECT status FROM long_offer WHERE id=?",String.class,offer));seats.maintain(next);assertEquals("INVALID",jdbc.queryForObject("SELECT status FROM long_offer WHERE id=?",String.class,offer));
    }
    @Test void stableWaitlistCannotPromoteSomeoneUnderACurrentPenaltyFromAnotherCycle() throws Exception {
        var admin=login("admin1");var one=login("student1");var two=login("student2");long old=open(admin,List.of(2000L,2001L),"promotion-old-cycle");submit(one,old,2000,"promotion-old-one");submit(two,old,2001,"promotion-old-two");draw(admin,old);
        for(var offer:jdbc.queryForList("SELECT id,user_id FROM long_offer WHERE batch_id=?",old))ok(api("POST","/long-offers/"+offer.get("id")+"/actions",Map.of("version",1,"action","ACCEPT"),Business.number(offer,"user_id")==1?one:two,"promotion-old-accept-"+offer.get("id")));
        var close=clock.value.plusSeconds(86400);long next=future(admin,close,"promotion-new-cycle");submit(one,next,2003,"promotion-new-one");submit(two,next,2003,"promotion-new-two");clock.value=close;admin=login("admin1");freezeFuture(admin,next);ok(allocateFuture(admin,next));long user=jdbc.queryForObject("SELECT user_id FROM waitlist_entry WHERE batch_id=? AND status='ACTIVE'",Long.class,next);var right=jdbc.queryForMap("SELECT e.id,e.offer_id FROM seat_entitlement e WHERE e.batch_id=? AND e.user_id=?",old,user);var record=create(new Fixture(admin,login(user==1?"student1":"student2"),old,Business.number(right,"offer_id"),Business.number(right,"id")));
        due(record.id());ok(decision(login("admin1"),record.id(),"REVOKE",iso(clock.value.plusSeconds(86400)),"promotion-penalty-revoke"));seats.maintain(next);assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM long_offer WHERE batch_id=? AND status='OPEN'",Integer.class,next));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM long_offer WHERE batch_id=?",Integer.class,next));assertEquals("ACTIVE",jdbc.queryForObject("SELECT status FROM waitlist_entry WHERE batch_id=? AND user_id=?",String.class,next,user));assertEquals("LONG_APPLICATION_PENALTY",api("GET","/preparation-batches/"+next+"/application",null,login(user==1?"student1":"student2"),null).data().at("/currentEligibility/reason").asString());
    }
